export async function ensureConventionCampaignTemplateSeed(database: Database): Promise<void> {
  const service = new BossWorkRequestService(database);
  const dave = (await database.select({ id: bossAccounts.id }).from(bossAccounts)
    .where(ilike(bossAccounts.displayName, "%dave%")).limit(1))[0];

  const legacyTemplates = await database.select({ id: communicationTemplates.id })
    .from(communicationTemplates)
    .where(inArray(communicationTemplates.code, [...legacyTemplateCodes]));
  const legacyTemplateIds = legacyTemplates.map((template) => template.id);

  if (legacyTemplateIds.length) {
    await database.update(communicationTemplates)
      .set({ state: "archived", updatedAt: new Date() })
      .where(inArray(communicationTemplates.id, legacyTemplateIds));

    const obsoleteRequests = await database.select({ id: bossWorkRequests.id })
      .from(bossWorkRequests)
      .innerJoin(
        communicationTemplateReviews,
        eq(communicationTemplateReviews.requestId, bossWorkRequests.id),
      )
      .where(and(
        inArray(communicationTemplateReviews.templateId, legacyTemplateIds),
        inArray(bossWorkRequests.state, ["waiting_on_dave", "in_progress", "changes_requested"]),
      ));
    const obsoleteRequestIds = obsoleteRequests.map((request) => request.id);
    if (obsoleteRequestIds.length) {
      await database.update(bossWorkRequests)
        .set({ state: "cancelled", completedAt: new Date(), updatedAt: new Date() })
        .where(inArray(bossWorkRequests.id, obsoleteRequestIds));
    }
  }

  for (const item of conventionCampaignTemplates) {
    const { gmailDraftId, gmailMessageId, ...templateValues } = item;
    const refreshedAt = new Date();
    const inserted = await database.insert(communicationTemplates).values({
      ...templateValues,
      channel: "email",
      category: "convention_campaign",
      accessScope: "office",
      state: "active",
      bodyFormat: "html",
      allowedPlaceholders: [
        "contactName",
        "eventName",
        "conventionName",
        "conventionDates",
        "boothOrMeetingLocation",
        "earlyBirdDeadline",
      ],
      requiredPlaceholders: ["contactName", "eventName", "conventionName", "earlyBirdDeadline"],
      ownerKind: "company",
      createdByKind: "system",
      sourceNote: `Gmail draft ${gmailDraftId} (message ${gmailMessageId}) with the approved Early Bird and convention-closing updates.`,
      reviewedBy: CONVENTION_FINALIZED_REVIEWER,
      reviewedAt: refreshedAt,
    }).onConflictDoUpdate({
      target: communicationTemplates.code,
      set: {
        templateVersion: templateValues.templateVersion,
        name: templateValues.name,
        subjectTemplate: templateValues.subjectTemplate,
        bodyTemplate: templateValues.bodyTemplate,
        bodyFormat: "html",
        allowedPlaceholders: [
          "contactName",
          "eventName",
          "conventionName",
          "conventionDates",
          "boothOrMeetingLocation",
          "earlyBirdDeadline",
        ],
        requiredPlaceholders: ["contactName", "eventName", "conventionName", "earlyBirdDeadline"],
        sourceNote: `Gmail draft ${gmailDraftId} (message ${gmailMessageId}) with the approved Early Bird and convention-closing updates.`,
        state: "active",
        reviewedBy: CONVENTION_FINALIZED_REVIEWER,
        reviewedAt: refreshedAt,
        updatedAt: refreshedAt,
      },
      setWhere: sql`
        excluded.template_version IS DISTINCT FROM ${communicationTemplates.templateVersion}
        or ${communicationTemplates.state} IS DISTINCT FROM 'active'
      `,
    }).returning();

    const template = inserted[0] ?? (await database.select().from(communicationTemplates)
      .where(eq(communicationTemplates.code, item.code)).limit(1))[0];
    if (!template) continue;

    const fingerprint = templateFingerprint({
      templateVersion: template.templateVersion,
      subjectTemplate: template.subjectTemplate,
      bodyTemplate: template.bodyTemplate,
      bodyFormat: template.bodyFormat,
    });

    const openReviewRequests = await database.select({ id: bossWorkRequests.id })
      .from(bossWorkRequests)
      .innerJoin(
        communicationTemplateReviews,
        eq(communicationTemplateReviews.requestId, bossWorkRequests.id),
      )
      .where(and(
        eq(communicationTemplateReviews.templateId, template.id),
        inArray(bossWorkRequests.state, [...openTemplateReviewStates]),
      ));
    const openReviewRequestIds = openReviewRequests.map((request) => request.id);
    if (openReviewRequestIds.length) {
      await database.update(bossWorkRequests)
        .set({
          state: "cancelled",
          completedAt: refreshedAt,
          updatedAt: refreshedAt,
          deduplicationKey: null,
        })
        .where(inArray(bossWorkRequests.id, openReviewRequestIds));
    }

    if (!dave || template.state === "active") continue;

    await service.createOwnerRequest({
      type: "email_template_approval",
      assignedBossAccountId: dave.id,
      title: `Review email template: ${template.name}`,
      instructions: "Please preview this convention email and approve it or leave notes for changes.",
      priority: "normal",
      dueAt: null,
      deduplicationKey: `template-review:${template.id}:${fingerprint}`,
      templateId: template.id,
      ownerId: "system:convention-template-seed",
    });
  }
}
